import UIKit

class CustomMenuControl: UIControl {
    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    var items: [UIAction] = [] {
        didSet {
            if items.isEmpty {
                contextMenuInteraction?.dismissMenu()
                isContextMenuInteractionEnabled = false
            } else {
                updateMenuIfVisible()
                isContextMenuInteractionEnabled = true
            }
        }
    }

    var selectedIndex: Int = -1 {
        didSet { updateMenuIfVisible() }
    }

    var showSelectedItem: Bool = true {
        didSet { updateMenuIfVisible() }
    }

    override var isHighlighted: Bool {
        didSet {
            titleLabel.isHighlighted = isHighlighted
            configureBackground(highlighted: isHighlighted)
        }
    }

    override func tintColorDidChange() {
        super.tintColorDidChange()
        titleLabel.textColor = tintColor
    }

    private lazy var titleLabel: UILabel = {
        let label = UILabel()
        label.textColor = tintColor
        label.highlightedTextColor = .secondaryLabel
        label.translatesAutoresizingMaskIntoConstraints = false
        addSubview(label)
        NSLayoutConstraint.activate([
            label.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 16),
            label.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -16),
            label.centerYAnchor.constraint(equalTo: centerYAnchor),
            heightAnchor.constraint(greaterThanOrEqualTo: label.heightAnchor),
            heightAnchor.constraint(greaterThanOrEqualToConstant: 44)
        ])
        return label
    }()

    private func configureBackground(highlighted: Bool) {
        backgroundColor = highlighted ? .systemGray2 : .systemGray5
        layer.cornerRadius = highlighted ? 8 : 16
        layer.cornerCurve = .continuous
    }

    override init(frame: CGRect) {
        super.init(frame: frame)
        showsMenuAsPrimaryAction = true
        configureBackground(highlighted: false)
        titleLabel.text = "Title"
    }

    convenience init(frame: CGRect, primaryAction: UIAction?) {
        self.init(frame: frame)
        if let primaryAction {
            addAction(primaryAction, for: .primaryActionTriggered)
            titleLabel.text = primaryAction.title
        }
    }

    private func updateMenuIfVisible() {
        contextMenuInteraction?.updateVisibleMenu { [unowned self] _ in self.menu }
    }

    private func proxyAction(_ action: UIAction, selected: Bool) -> UIAction {
        UIAction(title: action.title, image: action.image, discoverabilityTitle: action.discoverabilityTitle, attributes: action.attributes, state: selected ? .on : .off) { [weak self] proxy in
            guard let self, let control = proxy.sender as? CustomMenuControl else { return }
            control.selectedIndex = control.items.firstIndex(of: action) ?? -1
            control.sendAction(action)
            control.sendActions(for: .primaryActionTriggered)
        }
    }

    var menu: UIMenu {
        let selectedAction: UIAction? = showSelectedItem && selectedIndex >= 0 && selectedIndex < items.count ? items[selectedIndex] : nil
        return UIMenu(title: "", children: items.map { proxyAction($0, selected: $0 == selectedAction) })
    }

    override func contextMenuInteraction(_ interaction: UIContextMenuInteraction, configurationForMenuAtLocation location: CGPoint) -> UIContextMenuConfiguration? {
        UIContextMenuConfiguration(identifier: nil, previewProvider: nil) { [unowned self] _ in self.menu }
    }

    private func previewForMenuPresentation() -> UITargetedPreview {
        let previewTarget = UIPreviewTarget(container: titleLabel, center: titleLabel.center)
        let previewParameters = UIPreviewParameters()
        previewParameters.backgroundColor = .clear
        return UITargetedPreview(view: UIView(frame: titleLabel.frame), parameters: previewParameters, target: previewTarget)
    }

    override func contextMenuInteraction(_ interaction: UIContextMenuInteraction, previewForHighlightingMenuWithConfiguration config: UIContextMenuConfiguration) -> UITargetedPreview? {
        previewForMenuPresentation()
    }

    override func contextMenuInteraction(_ interaction: UIContextMenuInteraction, previewForDismissingMenuWithConfiguration config: UIContextMenuConfiguration) -> UITargetedPreview? {
        previewForMenuPresentation()
    }

    private func animateBackgroundHighlight(_ animator: UIContextMenuInteractionAnimating?, highlighted: Bool) {
        if let animator {
            animator.addAnimations { self.configureBackground(highlighted: highlighted) }
        } else {
            configureBackground(highlighted: highlighted)
        }
    }

    override func contextMenuInteraction(_ interaction: UIContextMenuInteraction, willDisplayMenuFor config: UIContextMenuConfiguration, animator: UIContextMenuInteractionAnimating?) {
        super.contextMenuInteraction(interaction, willDisplayMenuFor: config, animator: animator)
        animateBackgroundHighlight(animator, highlighted: true)
    }

    override func contextMenuInteraction(_ interaction: UIContextMenuInteraction, willEndFor config: UIContextMenuConfiguration, animator: UIContextMenuInteractionAnimating?) {
        super.contextMenuInteraction(interaction, willEndFor: config, animator: animator)
        animateBackgroundHighlight(animator, highlighted: false)
    }
}
