                DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) {
                    let items = (1...2).map { UIAction(title: "Dynamic Item \($0)") { _ in } }
                    completion([UIMenu(title: "", options: .displayInline, children: items)])
                }
